import {
    ArgumentMetadata, ParseArrayPipe, ParseBoolPipe, ParseDatePipe, ParseEnumPipe,
    ParseFloatPipe, ParseIntPipe, ParseUUIDPipe,
} from "@nestjs/common"

enum Color { Red = "red", Blue = "blue" }
const meta: ArgumentMetadata = { type: "query", data: "x" }

const cases: [string, () => unknown][] = [
    ["ParseIntPipe", () => new ParseIntPipe().transform("abc", meta)],
    ["ParseFloatPipe", () => new ParseFloatPipe().transform("1,5", meta)],
    ["ParseBoolPipe", () => new ParseBoolPipe().transform("ha", meta)],
    ["ParseArrayPipe", () => new ParseArrayPipe().transform(undefined, meta)],
    ["ParseUUIDPipe", () => new ParseUUIDPipe({ version: "4" }).transform("123", meta)],
    ["ParseEnumPipe", () => new ParseEnumPipe(Color).transform("green", meta)],
    ["ParseDatePipe", () => new ParseDatePipe().transform("kecha")],
]

async function main() {
    for (const [name, run] of cases) {
        try {
            await run()
        } catch (e: any) {
            console.log(name.padEnd(15), e.getStatus(), e.message)
        }
    }
}
main()

