import { Body, Controller, Module, Post, ValidationPipe } from "@nestjs/common"
import { registerDecorator, ValidationOptions } from "class-validator"

function IsUzPhone(options?: ValidationOptions) {
    return (object: object, propertyName: string) =>
        registerDecorator({
            name: "isUzPhone",
            target: object.constructor,
            propertyName,
            options: { message: `${propertyName} O'zbekiston raqami emas`, ...options },
            validator: {
                validate: (v: any) => typeof v === "string" && /^\+998(33|50|55|77|88|90|91|93|94|95|97|98|99)\d{7}$/.test(v),
            },
        })
}

