import { Controller, ExecutionContext, Get, Module, ValidationPipe, createParamDecorator } from "@nestjs/common"
import { Type } from "class-transformer"
import { IsIn, IsInt } from "class-validator"

class CurrentUserDto {
    @Type(() => Number) @IsInt() id: number
    @IsIn(["admin", "user"]) role: string
}

const CurrentUser = createParamDecorator((_data: unknown, ctx: ExecutionContext) => {
    const headers = ctx.switchToHttp().getRequest().headers
    return { id: headers["x-user-id"], role: headers["x-role"] }
})

@Controller("me")
class MeController {
    @Get() me(@CurrentUser() user: CurrentUserDto) { return user }
}

@Module({ controllers: [MeController] })
class AppModule {}

async function main() {
    const headers = { "x-user-id": "7", "x-role": "boss" }

    const off = await testApp(AppModule, app => app.useGlobalPipes(new ValidationPipe({ transform: true })))
    await off.get("/me", headers)
    await off.close()

    const on = await testApp(AppModule, app => app.useGlobalPipes(new ValidationPipe({ transform: true, validateCustomDecorators: true })))
    await on.get("/me", headers)
    await on.get("/me", { ...headers, "x-role": "admin" })
    await on.close()
}
main()

examples.output:
GET /me → 200 {"id":"7","role":"boss"}
GET /me → 400 {"message":["role must be one of the following values: admin, user"],"error":"Bad Request","statusCode":400}
GET /me → 200 {"id":7,"role":"admin"}

