import { ValidationPipe } from "@nestjs/common"
import { WsException } from "@nestjs/websockets"
import { IsString, MinLength } from "class-validator"

class ChatMessageDto {
    @IsString() @MinLength(1) text: string
    @IsString() room: string
}

const wsPipe = new ValidationPipe({
    exceptionFactory: errors =>
        new WsException(errors.flatMap(e => Object.values(e.constraints ?? {}))),
})

async function main() {
    const meta = { type: "body" as const, metatype: ChatMessageDto }

    const ok = await wsPipe.transform({ text: "Salom", room: "umumiy" }, meta)
    console.log("qabul qilindi:", JSON.stringify(ok))

    try {
        await wsPipe.transform({ text: 5 }, meta)
    } catch (e: any) {
