import { Body, Controller, Module, Post, ValidationPipe } from "@nestjs/common"
import { Transform } from "class-transformer"
import {
    IsEmail, IsOptional, IsStrongPassword, Matches, MinLength, Validate,
    ValidationArguments, ValidatorConstraint, ValidatorConstraintInterface,
} from "class-validator"

@ValidatorConstraint({ name: "sameAs" })
class SameAs implements ValidatorConstraintInterface {
    validate(value: unknown, args: ValidationArguments) {
        return value === (args.object as Record<string, unknown>)[args.constraints[0]]
    }
    defaultMessage(args: ValidationArguments) {
        return `${args.property} va ${args.constraints[0]} bir xil bo'lishi kerak`
    }
}

class RegisterDto {
    @Transform(({ value }) => String(value).trim().toLowerCase())
    @IsEmail({}, { message: "Email noto'g'ri" })
    email: string

    @IsStrongPassword(
        { minLength: 8, minLowercase: 1, minUppercase: 1, minNumbers: 1, minSymbols: 0 },
        { message: "Parol kamida 8 belgi, katta-kichik harf va raqamdan iborat bo'lsin" },
    )
    password: string

    @Validate(SameAs, ["password"])
    confirmPassword: string

    @IsOptional()
    @Matches(/^\+998\d{9}$/, { message: "Telefon +998XXXXXXXXX ko'rinishida bo'lsin" })
    phone?: string
}

