        const ext = file?.originalname.split(".").pop()?.toLowerCase() ?? ""
        return this.validationOptions.allowed.includes(ext)
    }
    buildErrorMessage(file: Express.Multer.File) {
        return `"${file.originalname}" kengaytmasi ruxsat etilmagan (mumkin: ${this.validationOptions.allowed.join(", ")})`
    }
}

@Controller("docs")
class DocsController {
    @Post()
    @UseInterceptors(FileInterceptor("file"))
    upload(@UploadedFile(new ParseFilePipe({ validators: [new ExtensionValidator({ allowed: ["pdf", "docx"] })] })) file: Express.Multer.File) {
        return { qabul: file.originalname }
    }
}

