import { BadRequestException, Controller, Get, Module, PipeTransform, Query } from "@nestjs/common"

class SortPipe implements PipeTransform {
    constructor(private readonly allowed: string[]) {}
    transform(value?: string) {
        if (!value) return {}
        const order: Record<string, "ASC" | "DESC"> = {}
        for (const part of value.split(",")) {
            const field = part.replace(/^-/, "")
            if (!this.allowed.includes(field)) throw new BadRequestException(`"${field}" bo'yicha saralab bo'lmaydi`)
            order[field] = part.startsWith("-") ? "DESC" : "ASC"
        }
        return order
    }
}

