import { BadRequestException, Body, Controller, Module, PipeTransform, Post, UsePipes } from "@nestjs/common"

type Rule = (v: any) => string | null
type Schema = Record<string, Rule>

const required: Rule = v => (v === undefined || v === "" ? "majburiy" : null)
const str = (min: number): Rule => v => (typeof v !== "string" || v.length < min ? `kamida ${min} belgili matn` : null)
const int = (min: number): Rule => v => (!Number.isInteger(v) || v < min ? `>= ${min} butun son` : null)

class SchemaPipe implements PipeTransform {
    constructor(private readonly schema: Schema) {}
    transform(body: any) {
        const errors: Record<string, string> = {}
        for (const [key, rule] of Object.entries(this.schema)) {
            const err = required(body?.[key]) ?? rule(body[key])
            if (err) errors[key] = err
        }
        if (Object.keys(errors).length) throw new BadRequestException({ errors })
        return body
    }
}

@Controller("courses")
class CoursesController {
    @Post()
    @UsePipes(new SchemaPipe({ title: str(3), hours: int(1) }))
    create(@Body() body: { title: string; hours: number }) { return { created: body } }
}

