import { Body, Controller, Injectable, Module, PipeTransform, Post } from "@nestjs/common"

@Injectable()
class StripHtmlPipe implements PipeTransform {
    private clean(v: any): any {
        if (typeof v === "string") return v.replace(/<[^>]*>/g, "").trim()
        if (Array.isArray(v)) return v.map(x => this.clean(x))
        if (v && typeof v === "object") return Object.fromEntries(Object.entries(v).map(([k, x]) => [k, this.clean(x)]))
        return v
    }
    transform(v: any) { return this.clean(v) }
}

