import { BadRequestException, PipeTransform } from "@nestjs/common"

class ParsePhonePipe implements PipeTransform<string, string> {
    transform(v: string) {
        const digits = v.replace(/\D/g, "")
        const full = digits.length === 9 ? "998" + digits : digits
        if (!/^998\d{9}$/.test(full)) throw new BadRequestException("Raqam noto'g'ri")
        return "+" + full
    }
}

const pipe = new ParsePhonePipe()
const cases = ["90 123 45 67", "+998 (91) 765-43-21", "998931112233", "12345"]
for (const input of cases) {
    try {
        console.log(`${input.padEnd(22)} → ${pipe.transform(input)}`)
    } catch (e: any) {
        console.log(`${input.padEnd(22)} → XATO: ${e.message}`)
    }
}

import { Body, Controller, Injectable, Module, PipeTransform, Post } from "@nestjs/common"

@Injectable()
class CamelCaseKeysPipe implements PipeTransform {
    private camel = (s: string) => s.replace(/_([a-z])/g, (_, c) => c.toUpperCase())
    private walk(v: any): any {
        if (Array.isArray(v)) return v.map(x => this.walk(x))
        if (v && typeof v === "object") {
            return Object.fromEntries(Object.entries(v).map(([k, x]) => [this.camel(k), this.walk(x)]))
        }
        return v
    }
    transform(v: any) { return this.walk(v) }
}

@Controller("import")
class ImportController {
    @Post() run(@Body(CamelCaseKeysPipe) body: any) { return body }
}

