import { BadRequestException, Body, Controller, Module, PipeTransform, Post, UsePipes } from "@nestjs/common"
import { z, type ZodType } from "zod"

class ZodValidationPipe implements PipeTransform {
    constructor(private readonly schema: ZodType) {}

    transform(value: unknown) {
        const result = this.schema.safeParse(value)
        if (!result.success) {
            throw new BadRequestException(result.error.issues.map(i => `${i.path.join(".")}: ${i.message}`))
        }
        return result.data
    }
}

const createCatSchema = z.object({
    name: z.string().min(2),
    age: z.coerce.number().int().min(0),
    color: z.string().default("kulrang"),
})
type CreateCatDto = z.infer<typeof createCatSchema>

@Controller("cats")
