import { BadRequestException, Controller, Get, Injectable, Module, PipeTransform, Query } from "@nestjs/common"

@Injectable()
class IdListPipe implements PipeTransform<string, number[]> {
    constructor(private readonly max = 5) {}
    transform(v: string) {
        const ids = String(v ?? "").split(",").filter(Boolean).map(Number)
        if (ids.some(n => !Number.isInteger(n) || n <= 0)) throw new BadRequestException("ID'lar musbat butun son bo'lsin")
        if (ids.length > this.max) throw new BadRequestException(`Ko'pi bilan ${this.max} ta ID`)
        return [...new Set(ids)]
    }
}

