import { ArgumentMetadata, BadRequestException, Body, Controller, Injectable, Module, PipeTransform, Post } from "@nestjs/common"
import { plainToInstance } from "class-transformer"
import { IsEmail, MinLength, validate } from "class-validator"

@Injectable()
class SimpleValidationPipe implements PipeTransform {
    async transform(value: unknown, { metatype }: ArgumentMetadata) {
        if (!metatype || !this.toValidate(metatype)) return value      // String, Number... tekshirilmaydi
        const object = plainToInstance(metatype, value)               // oddiy obyekt → DTO nusxasi
        const errors = await validate(object)                         // dekoratorlar bo'yicha tekshiruv
        if (errors.length > 0) throw new BadRequestException("Validatsiya xatosi")
        return value
    }

    private toValidate(metatype: Function): boolean {
        const types: Function[] = [String, Boolean, Number, Array, Object]
        return !types.includes(metatype)
    }
}

class SignupDto {
    @IsEmail() email: string
    @MinLength(8) password: string
}

@Controller("signup")
class SignupController {
    @Post() signup(@Body(SimpleValidationPipe) dto: SignupDto) { return { ok: true, email: dto.email } }
}

@Module({ controllers: [SignupController] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.post("/signup", { email: "ali@mail.uz", password: "12345678" })
    await http.post("/signup", { email: "ali", password: "123" })
    await http.close()
}
