import { ArgumentMetadata, Body, Controller, Injectable, Module, Param, PipeTransform, Put, Query, UsePipes } from "@nestjs/common"

@Injectable()
class NormalizePipe implements PipeTransform {
    transform(value: any, { type }: ArgumentMetadata) {
        switch (type) {
            case "param": return Number(value)                                      // :id → son
            case "query": return typeof value === "string" ? value.trim() : value   // bo'shliqlarni olib tashlash
            case "body": return { ...value, manba: "body" }                         // body'ga belgi qo'shish
            default: return value
        }
    }
