import { Controller, ExecutionContext, Get, Injectable, Module, PipeTransform, createParamDecorator } from "@nestjs/common"

type Pagination = { page: number; limit: number; skip: number }

const RawQuery = createParamDecorator((_data: unknown, ctx: ExecutionContext) => ctx.switchToHttp().getRequest().query)

@Injectable()
class PaginationPipe implements PipeTransform<Record<string, string>, Pagination> {
    transform(query: Record<string, string>) {
        const page = Math.max(1, parseInt(query.page ?? "1", 10) || 1)
        const limit = Math.min(50, Math.max(1, parseInt(query.limit ?? "10", 10) || 10))
        return { page, limit, skip: (page - 1) * limit }
    }
}

