import { Controller, Get, Injectable, Module, NotFoundException, PipeTransform, Query } from "@nestjs/common"

type Product = { id: number; name: string }

@Injectable()
class ProductsRepo {
    private items = new Map<number, Product>([[1, { id: 1, name: "Olma" }], [2, { id: 2, name: "Anor" }], [3, { id: 3, name: "Nok" }]])
    async find(id: number) {
        await new Promise(resolve => setTimeout(resolve, 5))     // "baza" so'rovi
        return this.items.get(id)
    }
}

@Injectable()
class ProductsByIdsPipe implements PipeTransform<string, Promise<Product[]>> {
    constructor(private readonly repo: ProductsRepo) {}

    async transform(value: string) {
        const ids = value.split(",").map(Number)
        const found = await Promise.all(ids.map(id => this.repo.find(id)))
        const missing = ids.filter((_, i) => !found[i])
        if (missing.length) throw new NotFoundException(`Topilmadi: ${missing.join(", ")}`)
        return found as Product[]
    }
}

@Controller("products")
class ProductsController {
    @Get() byIds(@Query("ids", ProductsByIdsPipe) products: Product[]) { return products.map(p => p.name) }
}

@Module({ controllers: [ProductsController], providers: [ProductsRepo] })
class AppModule {}

