import type { StandardSchemaV1 } from "@standard-schema/spec"
import { z } from "zod"

const toPath = (issue: StandardSchemaV1.Issue) =>
    (issue.path ?? []).map(segment => (typeof segment === "object" ? segment.key : segment)).join(".")

const pipe = new StandardSchemaValidationPipe({
    exceptionFactory: issues =>
        new UnprocessableEntityException({
            message: "Validation failed",
            errors: issues.map(issue => ({ path: toPath(issue), message: issue.message })),
        }),
})

