import { BadRequestException, Body, Controller, Module, Post, StandardSchemaValidationPipe } from "@nestjs/common"
import { z } from "zod"

const pipe = new StandardSchemaValidationPipe({
    exceptionFactory: issues => {
        const fields: Record<string, string[]> = {}
        for (const issue of issues) {
            const key = (issue.path ?? []).map(s => (typeof s === "object" ? s.key : s)).join(".") || "_"
            fields[key] = [...(fields[key] ?? []), issue.message]
        }
        return new BadRequestException({ fields })
    },
})

