import { ArgumentMetadata, BadRequestException, Body, Controller, Injectable, Module, PipeTransform, Post, Query, UsePipes } from "@nestjs/common"
import { z } from "zod"

@Injectable()
class AuditSchemaPipe implements PipeTransform {
    async transform(value: unknown, metadata: ArgumentMetadata) {
        if (!metadata.schema) return value                       // sxemasi yo'q argumentga tegmaymiz
        const std = metadata.schema["~standard"]
        const manba = metadata.data ? `${metadata.type}("${metadata.data}")` : metadata.type
        console.log(`sxema: ${std.vendor}, manba: ${manba}`)
        const result = await std.validate(value)
        if (result.issues) throw new BadRequestException(result.issues.map(issue => issue.message))
        return result.value
    }
}

@Controller("audit")
@UsePipes(AuditSchemaPipe)
class AuditController {
    @Post()
    save(
        @Body({ schema: z.object({ text: z.string().min(3) }) }) body: { text: string },
        @Query("lang", { schema: z.enum(["uz", "en"]).default("uz") }) lang: string,
        @Query("debug") debug?: string,
    ) {
        return { body, lang, debug }
    }
}

@Module({ controllers: [AuditController] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.post("/audit?debug=1", { text: "salom" })
    await http.post("/audit?lang=ru", { text: "salom" })
    await http.close()
}
main()

