const productSchema = z.object({ name: z.string().min(2), price: z.number().positive(), stock: z.number().int().min(0).default(0) })
const updateSchema = productSchema.partial()
const listSchema = z.object({ minPrice: z.coerce.number().min(0).default(0) })
const idSchema = z.coerce.number().int().positive()
const productOut = productSchema.extend({ id: z.number() })        // cost yo'q: javobda ko'rinmaydi

type Product = z.infer<typeof productOut> & { cost: number }

@Controller("products")
@UseInterceptors(StandardSchemaSerializerInterceptor)
@SerializeOptions({ schema: productOut })
class ProductsController {
    private items: Product[] = []

    @Post()
    create(@Body({ schema: productSchema }) dto: z.infer<typeof productSchema>) {
        const product = { id: this.items.length + 1, ...dto, cost: dto.price * 0.7 }
        this.items.push(product)
        return product
    }

    @Get()
    list(@Query({ schema: listSchema }) q: z.infer<typeof listSchema>) {
        return this.items.filter(p => p.price >= q.minPrice)
    }

    @Patch(":id")
    update(@Param("id", { schema: idSchema }) id: number, @Body({ schema: updateSchema }) dto: z.infer<typeof updateSchema>) {
        const product = this.items.find(p => p.id === id)
        if (!product) throw new NotFoundException(`Mahsulot #${id} topilmadi`)
        return Object.assign(product, dto)
    }
}

@Module({ controllers: [ProductsController] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule, app => app.useGlobalPipes(new StandardSchemaValidationPipe()))
    await http.post("/products", { name: "Choy", price: 15000 })
    await http.post("/products", { name: "Asal", price: 80000, stock: 5 })
    await http.post("/products", { name: "A", price: -1 })
    await http.get("/products?minPrice=20000")
    await http.patch("/products/1", { stock: 40 })
    await http.patch("/products/9", { stock: 1 })
    await http.close()
}
main()

