import {
    Body, Controller, DefaultValuePipe, Module, Param, ParseBoolPipe, ParseIntPipe, Patch, Query, StandardSchemaValidationPipe,
} from "@nestjs/common"
import { z } from "zod"

const updateSchema = z.strictObject({
    title: z.string().min(3).optional(),
    pages: z.number().int().min(1).optional(),
})

@Controller("books")
class BooksController {
    @Patch(":id")
    update(
        @Param("id", ParseIntPipe) id: number,
        @Query("notify", new DefaultValuePipe(false), ParseBoolPipe) notify: boolean,
        @Body({ schema: updateSchema }) dto: z.infer<typeof updateSchema>,
    ) {
        return { id, notify, dto }
    }
}

@Module({ controllers: [BooksController] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule, app => app.useGlobalPipes(new StandardSchemaValidationPipe()))
    await http.patch("/books/7?notify=true", { title: "Alpomish" })
    await http.patch("/books/abc", { title: "Alpomish" })
    await http.patch("/books/7", { pages: 0, year: 1999 })
    await http.close()
}
main()

